import hashlib, datetime

LOADER_MAP = {".pdf": PyPDFLoader, ".txt": TextLoader}

def load_document(path):
    ext = Path(path).suffix.lower()
    return LOADER_MAP[ext](path).load()

def chunk_documents(docs, chunk_size=512, chunk_overlap=50):
    splitter = RecursiveCharacterTextSplitter(
        chunk_size=chunk_size, chunk_overlap=chunk_overlap,
        separators=["\n\n", "\n", ". ", " "],
    )
    chunks = splitter.split_documents(docs)
    for i, chunk in enumerate(chunks):
        chunk.metadata["chunk_index"] = i
        chunk.metadata["chunk_id"] = hashlib.md5(chunk.page_content.encode()).hexdigest()[:12]
    return chunks

def embed_and_store(chunks, collection_name="knowledge_base"):
    client = QdrantClient("localhost", port=6333)
    embeddings = OpenAIEmbeddings(model="text-embedding-3-small")
    existing = [c.name for c in client.get_collections().collections]
    if collection_name not in existing:
        client.create_collection(
            collection_name=collection_name,
            vectors_config=VectorParams(size=1536, distance=Distance.COSINE),
        )
    for i in range(0, len(chunks), 100):
        batch = chunks[i:i+100]
        vectors = embeddings.embed_documents([c.page_content for c in batch])
        points = [
            PointStruct(
                id=i+j, vector=vectors[j],
                payload={"text": batch[j].page_content, "source": batch[j].metadata.get("source", "unknown")}
            )
            for j in range(len(batch))
        ]
        client.upsert(collection_name=collection_name, points=points)
    return len(chunks)

docs = load_document("policy_handbook.pdf")
chunks = chunk_documents(docs)
count = embed_and_store(chunks, "banking_policies")
print("Indexed {} chunks from {} pages".format(count, len(docs)))

import cohere
from sentence_transformers import CrossEncoder

class RerankingPipeline:
    def __init__(self):
        self.cohere_client = cohere.ClientV2("your-api-key")
        self.cross_encoder = CrossEncoder("cross-encoder/ms-marco-MiniLM-L-6-v2")

    def rerank(self, query, documents, top_k=5, use_cascade=True):
        if use_cascade and len(documents) > top_k * 3:
            stage1 = self._cohere_rerank(query, documents, top_n=20)
            stage2 = self._cross_encoder_rerank(query, stage1, top_n=top_k)
            return stage2
        return self._cohere_rerank(query, documents, top_n=top_k)

    def _cohere_rerank(self, query, documents, top_n=10):
        texts = [d["text"] if isinstance(d, dict) else d.page_content for d in documents]
        results = self.cohere_client.rerank(model="rerank-v3.5", query=query, documents=texts, top_n=top_n)
        return [{"text": r.document.text, "score": r.relevance_score} for r in results.results]

    def _cross_encoder_rerank(self, query, documents, top_n=5):
        texts = [d["text"] for d in documents]
        scores = self.cross_encoder.predict([(query, t) for t in texts])
        ranked = sorted(zip(texts, scores), key=lambda x: x[1], reverse=True)
        return [{"text": t, "score": float(s)} for t, s in ranked[:top_n]]

