import tiktoken

class ContextAssembler:
    def __init__(self, model="gpt-4o", max_tokens=8000):
        self.encoder = tiktoken.encoding_for_model(model)
        self.max_tokens = max_tokens

    def assemble(self, chunks):
        seen = set()
        unique = []
        for c in chunks:
            cid = c.get("chunk_id", c.get("text","")[:100])
            if cid not in seen:
                seen.add(cid)
                unique.append(c)
        unique.sort(key=lambda c: c.get("score", 0), reverse=True)

        selected, total_tokens = [], 0
        for chunk in unique:
            ctokens = len(self.encoder.encode(chunk["text"]))
            if total_tokens + ctokens <= self.max_tokens:
                selected.append(chunk)
                total_tokens += ctokens
            else:
                break

        context_parts, sources = [], []
        for i, chunk in enumerate(selected):
            ref = "[{}] {} (chunk: {})".format(i+1, chunk.get("source","unknown"), chunk.get("chunk_id","?"))
            context_parts.append("{}\n{}".format(ref, chunk["text"]))
            sources.append({"index": i+1, "source": chunk.get("source",""), "score": chunk.get("score",0)})

        return {"context": "\n\n---\n\n".join(context_parts), "token_count": total_tokens, "sources": sources}

