class SemanticCache:
    def __init__(self, threshold=0.92, ttl=3600):
        self.threshold = threshold
        self.ttl = ttl

    def get(self, query):
        query_vec = np.array(self._embed(query))
        for key in redis_client.scan_iter("rag_cache:*"):
            cached = json.loads(redis_client.get(key))
            sim = np.dot(query_vec, np.array(cached["embedding"])) / (np.linalg.norm(query_vec) * np.linalg.norm(np.array(cached["embedding"])))
            if sim >= self.threshold:
                return {**cached, "cache_hit": True, "similarity": float(sim)}
        return None

    def set(self, query, answer, sources):
        key = "rag_cache:{}".format(hash(query) % 100000)
        redis_client.setex(key, self.ttl, json.dumps({"query": query, "answer": answer, "sources": sources, "embedding": self._embed(query)}))

    def _embed(self, text):
        return client.embeddings.create(model="text-embedding-3-small", input=text).data[0].embedding

import re

class RAGGuardrails:
    INJECTION_PATTERNS = [
        r"ignore (previous|all) instructions",
        r"you are now (DAN|unrestricted)",
        r"system prompt",
        r"override safety",
    ]
    PII_PATTERNS = {
        "nric": r"[STFG]\d{7}[A-Z]",
        "email": r"[\w.-]+@[\w.-]+\.\w+",
        "phone": r"\+?65\s?\d{4}\s?\d{4}",
    }

    def check_input(self, query):
        for p in self.INJECTION_PATTERNS:
            if re.search(p, query, re.IGNORECASE):
                return {"safe": False, "reason": "injection_detected"}
        return {"safe": True}

    def sanitize_context(self, context):
        sanitized = context
        for pii_type, pattern in self.PII_PATTERNS.items():
            sanitized = re.sub(pattern, "[REDACTED_]" + pii_type.upper(), sanitized)
        return sanitized

    def check_output(self, answer):
        for pii_type, pattern in self.PII_PATTERNS.items():
            if re.search(pattern, answer):
                return {"safe": False, "reason": "pii_leak_" + pii_type}
        return {"safe": True}

