class RiskLevel(Enum):
    VERY_LOW = 1
    LOW = 2
    MEDIUM = 3
    HIGH = 4
    VERY_HIGH = 5


@dataclass
class NISTRisk:
    function: str  # GOVERN | MAP | MEASURE | MANAGE
    category: str
    risk_id: str
    description: str
    likelihood: RiskLevel
    impact: RiskLevel
    mitigations: List[str] = field(default_factory=list)
    residual: Optional[RiskLevel] = None
    status: str = "open"


class NISTRMF:
    def __init__(self, system_name: str):
        self.system_name = system_name
        self.risks: List[NISTRisk] = []

    def add_risk(self, risk: NISTRisk):
        self.risks.append(risk)

    def calculate_inherent_risk(self, risk: NISTRisk) -> int:
        return risk.likelihood.value * risk.impact.value

    def generate_register(self) -> dict:
        summary = {"very_low": 0, "low": 0, "medium": 0, "high": 0, "very_high": 0}
        for r in self.risks:
            score = self.calculate_inherent_risk(r)
            if score >= 20: level = "very_high"
            elif score >= 12: level = "high"
            elif score >= 6: level = "medium"
            elif score >= 3: level = "low"
            else: level = "very_low"
            summary[level] += 1
        return {
            "system": self.system_name,
            "generated": datetime.utcnow().isoformat(),
            "total_risks": len(self.risks),
            "risk_summary": summary,
            "by_function": {
                func: [r for r in self.risks if r.function == func]
                for func in ["GOVERN", "MAP", "MEASURE", "MANAGE"]
            }
        }

    def heatmap(self) -> dict:
        """5x5 risk heatmap matrix."""
        matrix = [[0]*5 for _ in range(5)]
        for r in self.risks:
            matrix[r.likelihood.value-1][r.impact.value-1] += 1
        return {"matrix": matrix, "legend": "Rows: likelihood (1-5), Cols: impact (1-5)"}

