            PDPAObligation("Part 3", "Consent", "Obtain express consent before collection, use, or disclosure", "check_consent"),
            PDPAObligation("Part 4", "Purpose Limitation", "Collect only for purposes a reasonable person would consider appropriate", "check_purpose"),
            PDPAObligation("Part 5", "Notification", "Inform individual of purpose on or before collection", "check_notification"),
            PDPAObligation("Part 6", "Access & Correction", "Provide access to personal data upon request, allow correction", "check_access"),
            PDPAObligation("Part 7", "Accuracy", "Make reasonable effort to ensure data accurate and complete", "check_accuracy"),
            PDPAObligation("Part 8", "Protection", "Protect data from unauthorized access, collection, use, disclosure", "check_protection"),
            PDPAObligation("Part 9", "Retention Limitation", "Retain only as long as necessary, dispose securely", "check_retention"),
            PDPAObligation("Part 10", "Transfer Restriction", "Cross-border transfers require comparable level of protection", "check_transfer"),
            PDPAObligation("Part 11", "Breach Notification", "Notify PDPC and affected individuals within 72 hours", "check_breach"),
            PDPAObligation("Part 12", "DPO Appointment", "Designate Data Protection Officer, publish contact info", "check_dpo"),
        ]

    def check_consent(self, config: dict) -> bool:
        return config.get("consent_obtained", False) and config.get("consent_is_explicit", False)

    def check_notification(self, config: dict) -> bool:
        return config.get("notification_provided", False) and config.get("notification_at_collection", False)

    def check_breach(self, config: dict) -> bool:
        return config.get("breach_response_plan", False) and config.get("breach_notification_time", 0) <= 72

    def run_compliance_check(self, config: dict) -> dict:
        results = {"compliant": [], "non_compliant": [], "not_applicable": []}
        for obl in self.obligations:
            check_fn = getattr(self, obl.checking_fn, None)
            if check_fn:
                try:
                    if check_fn(config):
                        results["compliant"].append(obl.name)
                    else:
                        results["non_compliant"].append(obl.name)
                except Exception:
                    results["not_applicable"].append(obl.name)
        return {
            "compliance_pct": round(len(results["compliant"]) / len(self.obligations) * 100, 1),
            "details": results,
            "checked_at": datetime.utcnow().isoformat(),
            "max_penalty_exposure": "10% of annual turnover" if results["non_compliant"] else "None"
        }

import json
from datetime import datetime
from enum import Enum
from typing import List, Callable, Dict


class ComplianceStatus(Enum):
    PASS = "pass"
    FAIL = "fail"
    WARN = "warn"
    ERROR = "error"
    SKIPPED = "skipped"


@dataclass
class ComplianceCheck:
    name: str
    framework: str  # gdpr | pdpa | eu_ai_act | iso42001 | nist_rmf
    category: str
    severity: str  # critical | high | medium | low
    check_fn: Callable[[], bool]
    evidence_fn: Optional[Callable[[], dict]] = None


class CompliancePipeline:
    def __init__(self):
        self.checks: List[ComplianceCheck] = []
        self.history: List[dict] = []

    def add_check(self, check: ComplianceCheck):
        self.checks.append(check)

    def run_all(self) -> dict:
        results = []
        for check in self.checks:
            try:
                passed = check.check_fn()
                evidence = check.evidence_fn() if check.evidence_fn else {}
                status = ComplianceStatus.PASS if passed else ComplianceStatus.FAIL
            except Exception as e:
                status = ComplianceStatus.ERROR
                evidence = {"error": str(e)}
            results.append({
                "check": check.name,
                "framework": check.framework,
                "category": check.category,
                "status": status.value,
                "severity": check.severity,
                "timestamp": datetime.utcnow().isoformat(),
                "evidence": evidence
            })
        self.history.extend(results)
        return self.summarize(results)

    def summarize(self, results: List[dict]) -> dict:
        by_framework = {}
        for r in results:
            by_framework.setdefault(r["framework"], {"pass": 0, "fail": 0, "total": 0})
            by_framework[r["framework"]]["total"] += 1
            by_framework[r["framework"]]["pass" if r["status"] == "pass" else "fail"] += 1
        return {
            "total": len(results),
            "passed": sum(1 for r in results if r["status"] == "pass"),
            "failed": sum(1 for r in results if r["status"] == "fail"),
            "errors": sum(1 for r in results if r["status"] == "error"),
            "critical_failures": [r for r in results if r["status"] == "fail" and r["severity"] == "critical"],
            "by_framework": by_framework,
            "timestamp": datetime.utcnow().isoformat()
        }

    def generate_evidence_package(self) -> dict:
        """Generate auditors-ready evidence bundle."""
        return {
            "generated_at": datetime.utcnow().isoformat(),
            "total_checks": len(self.history),
            "coverage": {
                fw: sum(1 for r in self.history if r["framework"] == fw)
                for fw in set(r["framework"] for r in self.history)
            },
            "all_evidence": [r["evidence"] for r in self.history if r.get("evidence")]
        }

