class TransferCompliance:
    """Multi-jurisdiction cross-border data transfer compliance."""

    MECHANISMS = {
        "GDPR": [
            TransferMechanism("Adequacy Decision", ["EU->UK", "EU->Japan", "EU->Korea"], ["Check EU adequacy list"]),
            TransferMechanism("Standard Contractual Clauses (SCCs)", ["EU->Any"], ["EU 2021/914 SCCs", "TIA", "Supplementary measures"]),
            TransferMechanism("Binding Corporate Rules (BCRs)", ["EU->Group entities"], ["DPA approval", "Annual audit"]),
        ],
        "PDPA": [
            TransferMechanism("Contractual Safeguards", ["SG->Any"], ["Comparable protection clauses", "Individual notification"]),
        ],
        "PIPL": [
            TransferMechanism("Security Assessment", ["CN->Any"], ["CAC approval for CII data", "Data export license"]),
            TransferMechanism("Standard Contract", ["CN->Any"], ["CAC standard contract", "PIA required"]),
        ]
    }

    def assess_transfer(self, from_jurisdiction: str, to_jurisdiction: str,
                        data_type: str, volume: str) -> dict:
        applicable = []
        for reg, mechs in self.MECHANISMS.items():
            for m in mechs:
                if m.jurisdictions[0].startswith(from_jurisdiction[:2]):
                    applicable.append({"regulation": reg, "mechanism": m.name,
                                       "requirements": m.requirements})

        risk_level = "LOW"
        if data_type in ["sensitive", "biometric", "genetic"] or volume == "high":
            risk_level = "HIGH"

        return {
            "transfer_path": f"{from_jurisdiction} -> {to_jurisdiction}",
            "risk_level": risk_level,
            "available_mechanisms": applicable,
            "required_actions": [
                "Conduct Transfer Impact Assessment (TIA)" if risk_level == "HIGH" else "Document transfer",
                "Implement appropriate safeguards" if not applicable else "Use available mechanism",
                "Update ROPA with transfer details",
                "Notify data subjects if required by local law"
            ]
        }

