    "violations": [],
    "last_scan": None
}


@app.get("/api/compliance/summary")
async def get_summary():
    systems = compliance_state["systems"]
    total = len(systems)
    compliant = sum(1 for s in systems.values() if s.get("status") == "compliant")
    return {
        "total_systems": total,
        "compliant": compliant,
        "non_compliant": total - compliant,
        "compliance_pct": round(compliant / total * 100, 1) if total else 0,
        "open_violations": len(compliance_state["violations"]),
        "last_scan": compliance_state["last_scan"]
    }


@app.post("/api/compliance/check/{system_id}")
async def check_system(system_id: str, evidence: dict):
    # Run compliance checks
    violations = [f for f in evidence.get("failures", [])]
    compliance_state["systems"][system_id] = {
        "status": "non_compliant" if violations else "compliant",
        "violations": violations,
        "checked_at": datetime.utcnow().isoformat()
    }
    compliance_state["violations"].extend(
        {"system": system_id, "violation": v, "timestamp": datetime.utcnow().isoformat()}
        for v in violations
    )
    compliance_state["last_scan"] = datetime.utcnow().isoformat()
    return {"status": "checked", "violations_found": len(violations)}


@app.get("/api/compliance/report")
async def generate_report():
    systems = compliance_state["systems"]
    report = {
        "generated_at": datetime.utcnow().isoformat(),
        "systems_checked": len(systems),
        "violations": compliance_state["violations"],
        "evidence_package": {
            sys_name: sys_data
            for sys_name, sys_data in systems.items()
            if sys_data["status"] == "compliant"
        },
        "remediation_required": [
            {"system": v["system"], "violation": v["violation"]}
            for v in compliance_state["violations"]
        ]
    }
    # In production: export to PDF, email to auditors
    return report


@app.websocket("/ws/compliance")
async def compliance_websocket(websocket: WebSocket):
    await websocket.accept()
    try:
        while True:
            # Push real-time compliance status updates
            await websocket.send_json({
                "systems": compliance_state["systems"],
                "recent_violations": compliance_state["violations"][-10:],
                "timestamp": datetime.utcnow().isoformat()
            })
            await asyncio.sleep(5)  # 5-second refresh
    except Exception:
        pass

from typing import List, Optional
from dataclasses import dataclass


class GuardrailType:
    PII_MASKING = "pii_masking"
    PROMPT_INJECTION = "prompt_injection"
    TOPIC_FILTERING = "topic_filtering"
    BIAS_CHECK = "bias_check"
    OUTPUT_VALIDATION = "output_validation"
    TOXICITY = "toxicity"


@dataclass
class GuardrailRequirement:
    guardrail_type: str
    regulation: str
    article: str
    severity: str
    configuration: dict


class GuardrailGRCBridge:
    """Maps regulatory requirements to technical guardrail configurations."""

    def __init__(self):
        self.mapping = [
            GuardrailRequirement(
                GuardrailType.PII_MASKING, "GDPR", "Art. 5(1)(c) - Data minimization",
                "critical", {"patterns": ["email", "phone", "nric", "passport"], "mask_char": "*"}
            ),
            GuardrailRequirement(
                GuardrailType.PII_MASKING, "PDPA", "Part 8 - Protection",
                "critical", {"patterns": ["nric", "fin", "passport", "phone"], "mask_char": "*"}
            ),
            GuardrailRequirement(
                GuardrailType.PROMPT_INJECTION, "EU AI Act", "Art. 15 - Robustness",
                "high", {"detection_model": "injection-classifier", "action": "block"}
            ),
            GuardrailRequirement(
                GuardrailType.TOPIC_FILTERING, "EU AI Act", "Art. 9 - Risk management",
                "high", {"blocked_topics": ["social scoring", "illegal content"], "action": "warn"}
            ),
            GuardrailRequirement(
                GuardrailType.BIAS_CHECK, "NIST AI RMF", "MEASURE - Bias testing",
                "high", {"metrics": ["demographic parity", "equal opportunity"], "threshold": 0.8}
            ),
            GuardrailRequirement(
                GuardrailType.OUTPUT_VALIDATION, "EU AI Act", "Art. 13 - Transparency",
                "medium", {"validate_claims": True, "check_grounding": True}
            ),
        ]

    def get_guardrails_for_jurisdiction(self, jurisdiction: str) -> List[dict]:
        return [
            {"type": r.guardrail_type, "config": r.configuration, "severity": r.severity}
            for r in self.mapping if jurisdiction.lower() in r.regulation.lower() or jurisdiction == "*"
        ]

    def generate_guardrail_config(self, systems: List[dict]) -> dict:
        """Generate unified guardrail configuration from compliance requirements."""
        config = {
            "global": {
                "pii_masking": {"enabled": True, "mask_char": "*", "patterns": ["email", "phone", "nric"]},
                "prompt_injection": {"enabled": True, "model": "injection-classifier-v2", "action": "block_and_log"},
                "toxicity_filter": {"enabled": True, "threshold": 0.7},
            },
            "system_overrides": {}
        }
        for system in systems:
            if system.get("jurisdiction"):
                overrides = self.get_guardrails_for_jurisdiction(system["jurisdiction"])
                if system.get("risk_level") == "high":
                    config["system_overrides"][system["name"]] = {
                        o["type"]: o for o in overrides
                    }
        return config

