import re
from typing import List, Dict


class PIIDetector:
    SINGAPORE_PATTERNS = {
        "nric": r"[STFG]\d{7}[A-Z]",
        "fin": r"[G]\d{7}[A-Z]",
        "phone": r"(?:\+65\s?)?\d{4}\s?\d{4}",
        "email": r"[\w.-]+@[\w.-]+\.\w+",
        "address": r"\d+[A-Z]\s+[A-Za-z ]+",  # Simplified
    }

    def detect(self, text: str) -> List[Dict]:
        detections = []
        for pii_type, pattern in self.SINGAPORE_PATTERNS.items():
            for match in re.finditer(pattern, text):
                detections.append({
                    "type": pii_type,
                    "value": match.group(),
                    "start": match.start(),
                    "end": match.end(),
                    "confidence": 0.95
                })
        return detections

    def mask(self, text: str) -> str:
        masked = text
        for pii_type, pattern in self.SINGAPORE_PATTERNS.items():
            masked = re.sub(pattern, f"[{pii_type.upper()}_REDACTED]", masked)
        return masked


class ContextIsolator:
    def __init__(self, max_context_tokens: int = 4000):
        self.max_tokens = max_context_tokens

    def sanitize_for_llm(self, documents: List[str]) -> str:
        """Remove sensitive data before sending to LLM."""
        detector = PIIDetector()
        sanitized = []
        for doc in documents:
            masked = detector.mask(doc)
            sanitized.append(masked)
        return "\n\n".join(sanitized)
